// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testFuzz_property(address from, address[] memory tosRaw, uint256 v) public {
        // Keep the array non-empty so the loop must run at least once.
        vm.assume(tosRaw.length > 0);
        // Widen but keep lengths reasonable for fuzzing.
        uint256 n = bound(tosRaw.length, 1, 10);
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = tosRaw.length > i ? tosRaw[i] : address(uint160(uint256(keccak256(abi.encode(tosRaw, i)))));
        }

        Recorder rec = new Recorder();
        c.transfer(from, address(rec), tos, v);

        // Reference calls once per recipient; the mutant starts at i=1 and skips the first.
        assertTrue(rec.count() == tos.length);
    }
}

contract Recorder {
    uint256 public count;
    function transferFrom(address, address, uint256) external {
        count++;
    }
}
